 f.common.state().actors.find("captain0")->location=WildernessLocation{"river","town",{50,50}};ActionCoreView action;action.id="action:8";action.kind="travel";action.actor_id="captain0";action.participants={"captain0","captain1"};f.common.state().actions.insert(action.id,action);for(const auto& id:action.participants)f.common.state().actors.find(id)->action_id=action.id;check(take(preview_naval_travel(f.common,f.military,f.mc,f.access,f.state,f.catalog,"captain0")).has_value(),"original shared travel can continue without a second action");
